125	  // The session log is also what awards the points: the server records the
126	  // GameSession, clamps the score and credits the account in one step, then
127	  // reports back what it actually granted. We trust that number, not ours —
128	  // the client no longer tells the backend how many points it deserves.
129	  const awardPoints = async (finalScore: number) => {
130	    if (awardedRef.current) return;
131	    awardedRef.current = true;
132	    if (!game) return;
133	    try {
134	      // apiFetch only attaches the JWT when one exists, so guests log anonymously
135	      // and are simply awarded nothing.
136	      const response = await apiFetch(`${BACKEND_ORIGIN}/trivia/log-session/`, {
137	        method: "POST",
138	        body: JSON.stringify({
139	          game: game.id,
140	          mode: "single",
141	          score: finalScore,
142	          duration_ms: playStartRef.current ? Date.now() - playStartRef.current : 0,
143	        }),
144	      });
145	      const data = await response.json().catch(() => ({}));
146	      if (data.error) showErrorAlert(data.error, "Saving your score failed!");
147	      else if (data.awarded > 0) dispatch(updatePoints(data.awarded));
148	    } catch (err) {
149	      console.error("Network error:", err);
150	    }
151	  };
